'use strict';
// execa 5's lib/promise.js (MIT); the mixin code is unchanged, applied here
// to checked objects instead of a spawned child process.
const nativePromisePrototype = (async () => {})().constructor.prototype;
const descriptors = ['then', 'catch', 'finally'].map(property => [
	property,
	Reflect.getOwnPropertyDescriptor(nativePromisePrototype, property)
]);

const mergePromise = (spawned, promise) => {
	for (const [property, descriptor] of descriptors) {
		const value = typeof promise === 'function' ?
			(...args) => Reflect.apply(descriptor.value, promise(), args) :
			descriptor.value.bind(promise);

		Reflect.defineProperty(spawned, property, {...descriptor, value});
	}

	return spawned;
};

async function run() {
  const out = [];
  const target = JSON.parse('{"name":"job"}');
  const merged = mergePromise(target, Promise.resolve('settled'));
  out.push(merged === target, typeof merged.then, Object.keys(merged).join(','));
  out.push(await merged);
  const lazy = mergePromise(JSON.parse('{}'), () => Promise.reject(new Error('lazy failure')));
  try { await lazy; } catch (error) { out.push(error.message); }
  out.push(await merged.then((v) => v + '!'));
  const thenable = { then(resolve) { resolve('plain thenable'); } };
  out.push(await thenable);
  return out;
}
module.exports = { run };
